/*
====================================================================================================
Division		|	Lidl
Solution		|	Operational Logistics (LOGOP)
DB schema		|	data
DB table		|	t_quintiq_reportedkpi_1
Description		|	QUINTIQ table for raw data
====================================================================================================
*/

CREATE TABLE DATA.t_quintiq_reportedkpi_1 (
client_id 	   NUMBER(38,0) NOT NULL COMMENT 'Client id - calculated based on the country_1 code',
lidl_country   VARCHAR(3)   NOT NULL COMMENT 'Country_1 code. Original field name bic_zmlila',
source_system  VARCHAR(30)  NOT NULL COMMENT 'Source system',
wh_id 		   VARCHAR(5)   NOT NULL COMMENT 'Warehouse ID',
store_stops_avg 				NUMBER(38,10) 	NULL		COMMENT 'The KPI counts the average number of stores that are visited during a tour_1',
dist_per_shift_avg 				NUMBER(38,10) 	NULL		COMMENT 'The KPI counts the average used distance per shift used for tours with store visits',
dur_per_shift_avg 				VARCHAR(512) 	NULL		COMMENT 'The KPI calculates the average used duration per shift used for tours with store visits',
costs_per_pallet_pos_sum 		NUMBER(38,10) 	NULL		COMMENT 'Costs per pallet position is defined as the total real costs divided by the total number of planned pallet positions (ShipmentLegs with ShipmentLeg.IsPlanned = true).',
delivery_dt 					DATE 			NOT NULL 	COMMENT 'Inidcates the delivery day of the reporting line ',
max_additional_dist_per_pallet 	NUMBER(38,10) 	NULL		COMMENT 'The largest AdditionalDistancePerPallet of all tours during a delivery day',
lanes_assigned_cnt 				NUMBER(38,10) 	NULL		COMMENT 'Total number of Lanes that have a Picklist assigned',
lanes_blocked_cnt 				NUMBER(38,10) 	NULL		COMMENT 'Total number of blocked lanes',
store_stops_cnt 				NUMBER(38,10) 	NULL		COMMENT 'The KPI counts the number of stops at a store over all tours',
tours_cnt 						NUMBER(38,10) 	NULL		COMMENT 'Count of the number of tours in the plan',
tours_elke_cnt 					NUMBER(38,10) 	NULL		COMMENT 'The number of tours with HasStoreDelivery = true is counted over all routes with at least one shipment planned (Route.IsUsed = true).',
tours_per_shift_cnt 			NUMBER(38,10) 	NULL		COMMENT 'Number of tours per shift ',
tours_per_shift_elke_cnt 		NUMBER(38,10) 	NULL		COMMENT 'This calculates the number of tours with store delivery per shift (= Company.NumToursElke / Company.TotalNumShiftsElke)',
planned_pos_cnt 				NUMBER(38,10) 	NULL		COMMENT 'The number of all pallet positions that need to be delivered to a non-RDC address_1(e.g. store) and are planned on the delivery day. This means the planned pallet positions excl.returns/collections is the sum of all ShipmentLeg.Quantity1 with ShipmentLeg.IsPlanned = true and ShipmentLeg.DeliveryAddress.Type <> RDC.',
duration_sum 					VARCHAR(512) 	NULL		COMMENT 'sum overall Route.TotalDuration with Route.IsUsed = true',
dur_per_shift_elke 				VARCHAR(512) 	NULL		COMMENT 'Total Duration/TotalNumShiftsElke',
pallets_1a_cnt 					NUMBER(38,10) 	NULL		COMMENT 'This calculates the number of 1a pallets (store deliveries). It sums all ShipmentLeg.Quantity1 with DeliveryAddress.IsStore = true',
pallets_1a_per_shift_elke_cnt 	NUMBER(38,10) 	NULL		COMMENT 'TotalNum1aPallets/TotalNumShiftsElke',
pallets_1b_cnt 					NUMBER(38,10) 	NULL		COMMENT 'This calculates the number of 1b pallets (returns and transfers). It counts all ShipmentLeg.Quantity1 with DeliveryAddress.IsStore = false',
paid_shifts_cnt 				NUMBER(38,10) 	NULL		COMMENT 'Total number of shifts used on resources with a shift-cost model',
paid_single_shift_routes_cnt 	NUMBER(38,10) 	NULL		COMMENT 'Total number of routes with single shifts on resources with a shif-cost model',
shifts_cnt 						NUMBER(38,10) 	NULL		COMMENT 'Total number of shifts used in the plan',
shifts_elke_cnt 				NUMBER(38,10) 	NULL		COMMENT 'Counts the number of shifts (Route.NumOfDriverShifts) in all used routes with store deliveries',
toll_costs_sum 					NUMBER(38,10) 	NULL		COMMENT 'The sum of all toll costs which are incurred during the activities of a resource',
routes_elke_cnt 				NUMBER(38,10) 	NULL		COMMENT 'Counts the number of routes that are in use for a store delivery',
dist_sum 						NUMBER(38,10) 	NULL		COMMENT 'Total distance planned in all routes with at least one planned shipment',
dist_elke_sum 					NUMBER(38,10) 	NULL		COMMENT 'The distance planned on all used tours with store deliveries',
dist_per_pallet_elke_sum 		NUMBER(38,10) 	NULL		COMMENT 'Used distance per number of pallets of type 1a',
dist_per_shift_elke_sum 		NUMBER(38,10) 	NULL		COMMENT 'Company.TotalUsedDistanceElke / Company.TotalNumShiftsElke',
dur_user_sum 					VARCHAR(512) 	NULL		COMMENT 'The sum of the user duration for all tours with store visits',
util_sum 						NUMBER(38,10) 	NULL		COMMENT 'Utilization over all resources and all shipments',
util_pallet_pos_elke 			NUMBER(38,10) 	NULL		COMMENT 'The average utilization of the resources that are going to stores over all tours that have store delivery',
util_wh_elke 					NUMBER(38,10) 	NULL		COMMENT 'The average of the utilization over all tours which have storedeliveries',
utilization_5_flop_tours_avg								NUMBER(38,10)		NULL	COMMENT 'This counts the average utilization of the five tours which have the highest AdditionalDistancePerPalletPosition',
constraint_violations_per_tour_avg                          NUMBER(38,10)       NULL	COMMENT 'The average constraint violations per TripForShipments is calculated by the number of constraint violations divided by the total number of TripForShipments that are planned for the delivery day',
cost_per_pallet_position_excl_pickup                        NUMBER(38,10)       NULL	COMMENT 'Costs per pallet position is defined as the total real costs divided by the total number of planned pallet position pallet positions (ShipmentLeg.Quantity1 with ShipmentLeg.IsPlanned = true) with ShipmentLeg.DeliveryAddress.Type <> RDC.',
store_stops_max_cnt                                         NUMBER(38,0)       	NULL	COMMENT 'The KPI counts the highest number of stops at a store during the delivery day',
product_decay_transport_max_qty                             NUMBER(38,10)       NULL	COMMENT 'Maximum product decay in transport over all shipments on a delivery day',
mins_outside_preferred_window_cnt                           NUMBER(38,10)       NULL	COMMENT 'Total minutes outside the preferred time window',
mins_outside_tolerance_window_cnt                           NUMBER(38,10)       NULL	COMMENT 'Total minutes outside the tolerances of the preferred time window',
addresses_max_drivers_hauliers_exceeded_cnt                 NUMBER(38,0)       	NULL	COMMENT 'Count of the number of addresses where the number of drivers or the number of hauliers per day is exceeded',
addresses_max_stops_per_delivery_day_exceeded_cnt           NUMBER(38,0)       	NULL	COMMENT 'The number of addresses where the maximum number of stops per delivery day are exceeded',
addresses_max_undelivered_exceeded_cnt                      NUMBER(38,0)       	NULL	COMMENT 'The number of addresses where the maximum number of undelivered pallets per delivery day are exceeded',
addresses_max_vehicles_exceeded_cnt                         NUMBER(38,0)       	NULL	COMMENT 'Count of the number of addresses where the number of vehicles per day is exceeded',
addresses_unmanned_pallet_positions_exceeded_cnt            NUMBER(38,0)       	NULL	COMMENT 'Count of the number of addresses where the number pallets delivered as an unmanned delivery per day is exceeded',
constraint_violations_cnt                                   NUMBER(38,0)       	NULL	COMMENT 'The number of constraint violations for the current plan over all routes.',
contract_allocations_exceeded_cnt                           NUMBER(38,0)       	NULL	COMMENT 'Count the number of contract allocations which are exceeded',
within_tolerance_delivery_performance_pct                   NUMBER(38,10)       NULL	COMMENT 'Percentage to indicate how many shipmenst deliverd to store are delivered within the preferred time window with tolerances',
utilization_time                                            NUMBER(38,10)       NULL	COMMENT 'Utilization of the available time of a resource',
utilization_deliveries_1                                    NUMBER(38,10)       NULL	COMMENT 'Utilization over all resources and outbound shipments (deliveries)',
unplanned_positions_cnt                                     NUMBER(38,10)       NULL	COMMENT 'The number of all pallet positions that need to be delivered to a non-RDC address_1 (e.g. store) and are still unplanned. This means the planned pallet positions excl. returns/collections is the sum of all ShipmentLeg.Quantity1 with ShipmentLeg.IsPlanned = false and ShipmentLeg.DeliveryAddress.Type <> RDC.',
max_additional_distance_per_pallet_tour_id                  VARCHAR(512)       	NULL	COMMENT 'The short ID of the tour_1 which had the largest AdditionalDistancePerPallet during a delivery day',
total_working_time_excess_qty                               NUMBER(38,10)       NULL	COMMENT 'Total duration of excess of working time for all drivers',
total_waiting_time_qty                                      NUMBER(38,10)       NULL	COMMENT 'The total amount of time spent waiting across all routes on this day. More specifically this is the sum of all hours (hh:mm_1) of the duration of the activities of type Waiting and Calendar_1 Event for this delivery day, in minutes as real',
paid_multi_shift_routes_total_cnt                           NUMBER(38,0)       	NULL	COMMENT 'Total number of routes with multi shifts on resources with a shif-cost model',
shift_indicator_elke_total_cnt                              NUMBER(38,10)       NULL	COMMENT 'Sum over all unique shiftIndicators which have IsStoreDelivery',
routes_in_use_total_cnt                                     NUMBER(38,0)       	NULL	COMMENT 'Total number of routes with at least one shipment leg planned',
driving_time_excess_total_sum                               NUMBER(38,10)       NULL	COMMENT 'Total duration of excess of driving time for all drivers',
most_stops_stores_id                                        VARCHAR(5000)      	NULL	COMMENT 'The KPI returns the ID of addresses which have the highest number of stops during the delivery day',
picklists_without_lane_incl_dummy_pct                       NUMBER(38,10)       NULL	COMMENT 'Picklists (including dummy_1) without a lane assigned in comparison to all picklists',
picklists_without_lane_pct                                  NUMBER(38,10)       NULL	COMMENT 'Picklists without a lane assigned in comparison to all picklists',
pallet_positions_without_lane_incl_dummy_pct                NUMBER(38,10)       NULL	COMMENT 'Pallet positions (including dummy_1) without a lane assigned in comparison to all pallet positions',
