above_max_multi_shift_pct                                   NUMBER(38,10)       NULL	COMMENT 'Percentage of routes with multi shift above the maximum multi shift percentage',
unplanned_pallet_positions_store_deliveries_cnt             NUMBER(38,10)       NULL	COMMENT 'Sums the total unplanned and planned for next day pallet positions to stores',
