invalid_resource_dimensions_stops_cnt                       NUMBER(38,0)       	NULL	COMMENT 'The total count of unique stops where the resource dimension is incorrect.',
constraint_violations_tour_cnt                              NUMBER(38,0)       	NULL	COMMENT 'The number of trips (tours) with constraint violations counts the TripForShipments which have at least one constraint violated.',
